function productDefaults(){defaults({editNode:'start',drafts:[],constraint:'主角不使用暴力；伙伴不独自离开'})}
function graphCheck(){const missing=[],seen=new Set();function visit(id){if(seen.has(id))return;seen.add(id);const n=state.nodes[id];if(!n){missing.push(id);return}for(const c of n.choices||[])visit(c.next)}visit('start');return {missing,unreachable:Object.keys(state.nodes).filter(x=>!seen.has(x)),endings:Object.values(state.nodes).filter(x=>x.ending).length}}
function productRender(){const g=graphCheck(),n=state.nodes[p.editNode]||state.nodes.start;put(`<div class="grid"><div>${box('分镜与分支结构',`<div class="stack">${Object.entries(state.nodes).map(([id,x])=>`<div class="node-editor"><button data-node="${esc(id)}" class="small">${esc(x.title)} / ${esc(id)}</button><p>${x.ending?'结局':(x.choices||[]).map(c=>esc(c.label)+' → '+esc(c.next)).join('<br>')}</p></div>`).join('')}</div><p>结局 ${g.endings} 个；缺失目标 ${g.missing.length} 个；暂不可达节点 ${g.unreachable.length} 个。</p>${g.unreachable.length?note('暂不可达：'+g.unreachable.map(esc).join('、')):''}`)}${box('编辑选择与结局',`<form id="node-edit" class="stack">${field('正在编辑的节点','id','text',p.editNode,'required readonly')}${field('镜头标题','title','text',n.title,'required maxlength="60"')}<label>镜头文字<textarea name="text" maxlength="1200" required>${esc(n.text)}</textarea></label>${select('节点类型','type',['剧情','结局'],n.ending?'结局':'剧情')}<label>选择（每行：文字 | 目标节点ID）<textarea name="choices" maxlength="1500">${(n.choices||[]).map(x=>esc(x.label)+' | '+esc(x.next)).join('\n')}</textarea></label>${field('结局回顾','lesson','text',n.lesson||'','maxlength="240"')}<button>保存镜头与连接</button></form>`)}</div><div>${box('新增镜头',`<form id="node-add" class="stack">${field('唯一ID（英文字母和数字）','id','text','','required pattern="[a-zA-Z][a-zA-Z0-9_-]{0,19}" maxlength="20"')}${field('镜头名称','title','text','','required maxlength="60"')}<button>添加一个结局草稿</button></form>${note('先添加节点，再在其他镜头中写入它的ID，建立可到达的分支。')}`)}${box('故事版本库',`<form id="story-save" class="stack">${field('版本名称','name','text','','required maxlength="50"')}<button>保存当前故事版本</button></form>${rows(p.drafts,x=>`<div class="item"><span>${esc(x.name)}</span><button data-version="${x.id}" class="small">载入</button></div>`)}`)}${box('导演约束',`<form id="constraint" class="stack"><label>故事必须遵守<textarea name="constraint" required maxlength="400">${esc(p.constraint)}</textarea></label><button>保存创作约束</button></form>${note('程序检查分支引用，不自动审查文字是否符合约束；由作者与同伴逐段核对。')}`)}</div></div>`);deleteButtons('node',id=>{p.editNode=id;commit()});form('node-add',v=>{if(Object.hasOwn(state.nodes,v.id)||['constructor','prototype','__proto__'].includes(v.id))return toast('请使用新的有效节点ID');state.nodes[v.id]={title:v.title,text:'在这里写下你的新结局。',ending:true,lesson:'这个选择带来了什么？'};p.editNode=v.id;commit()});form('node-edit',v=>{const next={title:v.title,text:v.text,ending:v.type==='结局'};if(next.ending)next.lesson=v.lesson;else{const lines=v.choices.split('\n').filter(x=>x.trim());const choices=lines.map(x=>{const a=x.split('|');return {label:a[0]?.trim(),next:a[1]?.trim()}});if(!choices.length||choices.length>4||choices.some(x=>!x.label||!state.nodes[x.next]))return toast('剧情需1—4个选择，每行用 | 连接已有目标ID');next.choices=choices}state.nodes[v.id]=next;commit()});form('story-save',v=>{p.drafts.push({id:uid(),name:v.name,nodes:clone(state.nodes),hero:state.hero,partner:state.partner});commit()});deleteButtons('version',id=>{const x=p.drafts.find(x=>x.id===id);state.nodes=clone(x.nodes);state.hero=x.hero;state.partner=x.partner;state.current='start';state.path=[];state.endings=[];p.editNode='start';commit()});form('constraint',v=>{p.constraint=v.constraint;commit()})}
